// component.js
class AnthropicProvider {
  constructor(apiKey) {
    this.apiKey = apiKey;
    this.baseUrl = "https://anthropic.com";
  }

  async sendPayload({ model = "claude-3-5-sonnet-20241022", messages, system, tools }) {
    const response = await fetch(this.baseUrl, {
      method: "POST",
      headers: {
        "x-api-key": this.apiKey,
        "anthropic-version": "2023-06-01",
        "content-type": "application/json",
      },
      body: JSON.stringify({
        model: model,
        max_tokens: 4096,
        system: system,     // Your custom managed system prompt
        messages: messages, // Your custom managed message window
        tools: tools        // Your custom tool definitions
      }),
    });

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(`Anthropic API Error: ${errorData.error?.message || response.statusText}`);
    }

    return await response.json();
  }
}

// Example Initialization
const provider = new AnthropicProvider(process.env.ANTHROPIC_API_KEY);
